"use client";

import { useEffect, useRef } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

const nodes = [
    {
        id: "request",
        title: "REQUEST",
        subtitle: "POST /v1/chat/completions",
    },
    {
        id: "auth",
        title: "AUTH",
        subtitle: "Clerk JWT",
    },
    {
        id: "intent",
        title: "INTENT ANALYSIS",
        subtitle: "Classify task complexity",
    },
    {
        id: "budget",
        title: "BUDGET",
        subtitle: "Token enforcement",
    },
    {
        id: "router",
        title: "MODEL ROUTER",
        subtitle: "Choose provider",
    },
];

export default function IntentScope() {
    const sectionRef = useRef<HTMLElement>(null);

    useEffect(() => {
        const ctx = gsap.context(() => {
            gsap.from(".intent-project", {
                opacity: 0,
                y: 50,
                duration: 0.8,
                ease: "power3.out",
                scrollTrigger: {
                    trigger: sectionRef.current,
                    start: "top 75%",
                },
            });

            gsap.from(".architecture-node", {
                opacity: 0,
                x: 30,
                stagger: 0.08,
                duration: 0.5,
                ease: "power3.out",
                scrollTrigger: {
                    trigger: ".architecture",
                    start: "top 75%",
                },
            });

            gsap.from(".provider-card", {
                opacity: 0,
                y: 20,
                stagger: 0.1,
                duration: 0.5,
                ease: "power3.out",
                scrollTrigger: {
                    trigger: ".provider-grid",
                    start: "top 80%",
                },
            });
        }, sectionRef);

        return () => ctx.revert();
    }, []);

    return (
        <section
            ref={sectionRef}
            id="projects"
            className="intent-section"
        >
            <div className="intent-top">
                <span>01 / DISTRIBUTED AI SYSTEM</span>

                <span>2026</span>
            </div>

            <div className="intent-project">
                {/* LEFT */}
                <div className="intent-project-info">
                    <div className="intent-number">
                        01
                    </div>

                    <h2>INTENTSCOPE</h2>

                    <p className="intent-tagline">
                        Intent-driven adaptive scoping
                        for LLM APIs.
                    </p>

                    <p className="intent-description">
                        A smart API gateway that sits between
                        applications and multiple LLM providers.
                        It analyzes request intent, intelligently
                        routes models, enforces token budgets
                        and provides centralized observability.
                    </p>

                    <div className="intent-stack">
                        <span>PYTHON</span>
                        <span>GO</span>
                        <span>NEXT.JS</span>
                        <span>POSTGRES</span>
                        <span>DOCKER</span>
                        <span>LLM</span>
                    </div>

                    <div className="intent-actions">
                        <a
                            href="https://your-live-demo-url.com"
                            target="_blank"
                            rel="noopener noreferrer"
                            className="project-primary-button"
                        >
                            LIVE DEMO
                            <span>↗</span>
                        </a>

                        <a
                            href="https://github.com/yourusername/intent-scope"
                            target="_blank"
                            rel="noopener noreferrer"
                            className="project-secondary-button"
                        >
                            GITHUB
                            <span>↗</span>
                        </a>
                    </div>
                </div>

                {/* RIGHT */}
                <Architecture />
            </div>
        </section>
    );
}

function Architecture() {
    return (
        <div className="architecture">
            <div className="architecture-label">
                REQUEST FLOW
            </div>

            <div className="architecture-flow">
                {nodes.map((node, index) => (
                    <div
                        key={node.id}
                        className="architecture-step"
                    >
                        <div className="architecture-node">
                            <span className="architecture-index">
                                0{index + 1}
                            </span>

                            <div>
                                <strong>{node.title}</strong>

                                <small>
                                    {node.subtitle}
                                </small>
                            </div>
                        </div>

                        {index < nodes.length - 1 && (
                            <div className="architecture-line">
                                <span />
                            </div>
                        )}
                    </div>
                ))}
            </div>

            <div className="routing-area">
                <div className="routing-label">
                    MODEL ROUTING
                </div>

                <div className="provider-grid">
                    <Provider
                        name="GROQ"
                        type="LIGHT"
                        detail="llama-3.1-8b"
                        accent="violet"
                    />

                    <Provider
                        name="MISTRAL"
                        type="HEAVY"
                        detail="mistral-large"
                        accent="blue"
                    />

                    <Provider
                        name="OLLAMA"
                        type="LOCAL"
                        detail="llama3.2"
                        accent="lime"
                    />
                </div>
            </div>
        </div>
    );
}

function Provider({
    name,
    type,
    detail,
    accent,
}: {
    name: string;
    type: string;
    detail: string;
    accent: "violet" | "blue" | "lime";
}) {
    return (
        <div className={`provider-card provider-${accent}`}>
            <span>{type}</span>

            <strong>{name}</strong>

            <small>{detail}</small>

            <div className="provider-status">
                <i />
                AVAILABLE
            </div>
        </div>
    );
}